def analyze_shape(grid):
    """Analyze the shapes of each color."""
    shapes = {}
    visited = set()
    n, m = 10, 10

    for r in range(n):
        for c in range(m):
            if grid[r][c] != 0 and (r, c) not in visited:
                color = grid[r][c]
                cells = []
                stack = [(r, c)]
                while stack:
                    pr, pc = stack.pop()
                    if (pr, pc) in visited:
